# Generated by Phase: IMPLEMENT | Feature: EVOL-079
"""The backlog lifecycle (EVOL-079) — the board tells the truth about the work, on every adapter.

config   `config/quality.json → tracker`: `adapter` (github | jira | none — derived at SETUP from Q27) and `flow` (the
         project's board column for each lifecycle state, in order: backlog, ready, in progress, done — Q27.7). The
         tracker ids live in `docs/backlog/project-config.json → project_ids` (`--init-board` captures them): GitHub
         `owner`, `repo`, `project_number` (`project_node_id` when known); Jira `site`, `project_key`, `board_id`.
shape    one board for every adapter: {columns: [name], items: [{key, title, column, parent, labels, closed, ref}],
         relink, closable} — `key` the issue number (GitHub), the issue key (Jira) or the local id (none); `parent` the
         parent's key; `column` None when the item is not on the board (GitHub: an open issue never added to the project).
identity an item's ident is its title head: up to and including the phase token's colon (`[FEAT-001] IMPLEMENT:`,
         `[FEAT-001] INC-1 / SUB-1-2:`), or a full title a row names (`ident`). A title matches when it equals the ident;
         a head (ending in its colon, or a bracketed id with no colon) also matches a title that continues it after a
         blank (or a colon, for the bracketed id). A whole title matches only itself. Two items on one ident: red.
planner  pure — `plan_move` / `plan_ensure` return the requests (`move`, `create`, `link`); a board already in the
         wanted state plans nothing: that is the idempotency. Every write is followed by a re-read (the keys written
         read back one by one) and the same plan: anything left is red.
commands `gate.py tracker --start --feature F --phase P | --item IDENT [--aligns AC-F-N]` — the item In Progress before
         the work (a Done item stays Done only for a ratified realignment); `--move IDENT --to STATE`; `--ensure FILE |
         --sub-increments F [--dry-run]` — missing items created in their state's column, a parentless child linked,
         nothing else touched.
transport github `gh api graphql` (the pre-authenticated CLI; the Status field and its options by name, no id stored) ·
         jira REST over urllib — a site under atlassian.net is Cloud (api/3, search/jql with token paging, Basic
         email:token, ADF), any other is Data Center (api/2, search with startAt paging, Bearer personal token);
         JIRA_API_TOKEN (+ JIRA_USER_EMAIL on Cloud) from the environment, never a file · none `docs/backlog/state.md`.
"""
from __future__ import annotations

import base64
import datetime as dt
import json
import os
import re
import subprocess
import urllib.parse
from pathlib import Path

from . import aligned as aligned_mod
from . import rest
from . import train as train_mod
from .common import FM_RE, GateFault, clean, key, parse_yaml, read_frontmatter

ADAPTERS = ("github", "jira", "none")
STATES = ("backlog", "ready", "in-progress", "done")
PHASES = ("codesign", "blueprint", "contract-freeze", "devops", "implement", "preventive-sweep", "qa", "smoke")
SIMPLIFIED = {"codesign": "SPEC", "blueprint": "SPEC", "contract-freeze": "IMPLEMENT", "devops": "IMPLEMENT", "implement": "IMPLEMENT",
              "preventive-sweep": "IMPLEMENT", "qa": "QA", "smoke": "QA"}
CONFIG = "docs/backlog/project-config.json"
STATE = "docs/backlog/state.md"
BODIES = "docs/backlog/issue-bodies"
FEATURE_RE = re.compile(r"^[A-Za-z][A-Za-z0-9_-]*$")
PHASED_RE = re.compile(r"^\[[^\]]+\] [A-Z][A-Z0-9-]*(?: \([^)]*\))?(?: / [A-Z0-9-]+)?:")
JIRA_KEY = re.compile(r"^[A-Z][A-Z0-9_]+\Z")
JIRA_ISSUE = re.compile(r"^[A-Z][A-Z0-9_]+-\d+\Z")
GH_NAME = re.compile(r"^[A-Za-z0-9._-]+\Z")
JIRA_FIELDS = ["summary", "status", "parent", "labels", "issuetype"]
LOCAL_COLS = ("Local ID", "Feature", "Title", "Status", "Labels", "Milestone", "Parent", "Body File")
EMPTY = ("", "—", "-")


# ─── config ─────────────────────────────────────────────────────────────────────

def cfg(repo: Path) -> dict:
    t = key(repo, "tracker", default=None)
    if not isinstance(t, dict):
        raise GateFault("config key `tracker` is missing from config/quality.json — the adapter and the flow live there (SETUP Q27 materialises them; SETUP --upgrade adds them)")
    a = t.get("adapter")
    if a not in ADAPTERS:
        raise GateFault(f"tracker.adapter `{clean(a)}` is not one of {', '.join(ADAPTERS)}")
    flow = t.get("flow")
    if not (isinstance(flow, list) and len(flow) == len(STATES) and all(isinstance(c, str) and c.strip() for c in flow)):
        raise GateFault("tracker.flow is the project's board column for backlog, ready, in progress and done — four column names, in that order")
    return {"adapter": a, "flow": dict(zip(STATES, (c.strip() for c in flow)))}


def ids(repo: Path) -> dict:
    p = repo / CONFIG
    try:
        doc = json.loads(p.read_text(encoding="utf-8"))
    except FileNotFoundError:
        raise GateFault(f"{CONFIG} is missing — `BACKLOG --init-board` creates the board and records its ids there") from None
    except (OSError, ValueError) as e:
        raise GateFault(f"{CONFIG} is not readable JSON ({e})") from None
    got = doc.get("project_ids") if isinstance(doc, dict) else None
    return got if isinstance(got, dict) else {}


def preset(repo: Path) -> str:
    fm = read_frontmatter(repo / "docs/setup.md")
    pt = fm.get("project_tracking") if isinstance(fm, dict) else None
    p = pt.get("feature_phases") if isinstance(pt, dict) else None
    return p if p in ("full-sdlc", "simplified", "single") else "full-sdlc"   # the production default (BOPS § 1.1)


# ─── identity ───────────────────────────────────────────────────────────────────

def head(title: str) -> str:
    t = str(title).strip()
    return t[: t.index(":") + 1] if t.startswith("[") and ":" in t else t


def matches(title: str, ident: str) -> bool:
    """A head (`… PHASE:`) goes on with a space; a bracketed name with no colon (`[F]`, `[F] SMOKE-E2E`) with a space or a
    colon; any other ident is a whole title and matches only itself (`[F] COMPONENT: Button` is never `… Button Group`)."""
    t = str(title).strip()
    if t == ident:
        return True
    if ident.endswith(":"):
        return t.startswith(ident + " ")
    return ident.startswith("[") and ":" not in ident and (t.startswith(ident + " ") or t.startswith(ident + ":"))


def phase_ident(feature: str, phase: str, kind: str) -> str:
    if not FEATURE_RE.match(str(feature or "")):
        raise GateFault(f"`{clean(feature)}` is not a feature id")
    if phase not in PHASES:
        raise GateFault(f"`{clean(phase)}` is not a phase ({', '.join(PHASES)})")
    if kind == "single":
        return f"[{feature}]"
    if kind == "simplified":
        return f"[{feature}] {SIMPLIFIED[phase]}:"
    return f"[{feature}] SMOKE-E2E" if phase == "smoke" else f"[{feature}] {phase.upper()}:"


def find(board: dict, ident: str) -> list[dict]:
    single = bool(re.fullmatch(r"\[[^\]]+\]", ident))   # the single preset: the feature's one item, never a phase-headed one
    return [i for i in board["items"] if matches(i["title"], ident) and not (single and PHASED_RE.match(i["title"]))]


def _where(board: dict, col: str) -> None:
    if col not in board["columns"]:
        raise GateFault(f"the flow names column `{clean(col)}` and the board has none — its columns: {', '.join(board['columns']) or '(none)'}; "
                        "fix config/quality.json → tracker.flow or the board")


def _flow_on(board: dict, flow: dict) -> None:
    """Every column of the flow is on the board — checked on every read, so a wrong flow faults at once, never at its first move."""
    for state in STATES:
        _where(board, flow[state])


# ─── planner (pure) ─────────────────────────────────────────────────────────────

def plan_move(board: dict, item: dict, column: str, done: str) -> list[dict]:
    _where(board, column)
    close = column == done
    if item["column"] != column or (board.get("closable") and item["closed"] != close):
        return [{"op": "move", "key": item["key"], "column": column, "close": close}]
    return []


def _row(r, i: int) -> dict:
    if not isinstance(r, dict) or not isinstance(r.get("title"), str) or not r["title"].strip():
        raise GateFault(f"ensure row {i}: needs a `title`")
    bad = set(r) - {"title", "ident", "body", "labels", "parent", "milestone", "state"}
    if bad:
        raise GateFault(f"ensure row {i}: unknown field(s) {', '.join(sorted(bad))} — a row is {{title, ident?, body?, labels?, parent?, milestone?, state?}}")
    if r.get("state", "backlog") not in STATES:
        raise GateFault(f"ensure row {i}: state `{clean(r.get('state'))}` is not one of {', '.join(STATES)}")
    labels = r.get("labels", [])
    if not (isinstance(labels, list) and all(isinstance(x, str) and x.strip() for x in labels)):
        raise GateFault(f"ensure row {i}: `labels` is a list of label names")
    for k in ("ident", "body", "parent", "milestone"):
        if k in r and r[k] is not None and not (isinstance(r[k], str) and r[k].strip()):
            raise GateFault(f"ensure row {i}: `{k}` is a non-empty string")
    return {"title": r["title"].strip(), "ident": (r.get("ident") or head(r["title"])).strip(), "body": r.get("body"),
            "labels": labels, "parent": r.get("parent"), "milestone": r.get("milestone"), "state": r.get("state", "backlog")}


def plan_ensure(board: dict, rows: list, flow: dict) -> tuple[list[dict], list[str]]:
    rows = [_row(r, i + 1) for i, r in enumerate(rows)]
    _flow_on(board, flow)
    reqs, red, made, seen = [], [], set(), set()
    for r in rows:
        if r["ident"] in seen:
            red.append(f"two rows name the item `{r['ident']}` — one row per item; pass `ident` = the whole title when items share a head")
            continue
        seen.add(r["ident"])
        hits = find(board, r["ident"])
        if len(hits) > 1:
            red.append(f"`{r['ident']}` matches {len(hits)} items ({', '.join(h['key'] for h in hits)}) — a duplicate; close the extra one by hand")
            continue
        pkey, new_parent = None, False
        if r["parent"]:
            ph = find(board, r["parent"])
            if len(ph) > 1:
                red.append(f"`{r['title']}`: its parent `{r['parent']}` matches {len(ph)} items ({', '.join(h['key'] for h in ph)})")
                continue
            if not ph and r["parent"] not in made:
                red.append(f"`{r['title']}`: its parent `{r['parent']}` is not on the board and no earlier row creates it")
                continue
            pkey, new_parent = (ph[0]["key"], False) if ph else (None, True)
        if not hits:
            reqs.append({"op": "create", "ident": r["ident"], "title": r["title"], "body": r["body"], "labels": r["labels"],
                         "milestone": r["milestone"], "parent": r["parent"], "column": flow[r["state"]], "close": flow[r["state"]] == flow["done"]})
            made.add(r["ident"])
            continue
        it = hits[0]
        if r["parent"] and (new_parent or it["parent"] != pkey):
            if it["parent"] is not None:
                red.append(f"{it['key']} `{it['title']}` sits under {it['parent']}, not under `{r['parent']}` — the reader never re-parents; move it by hand")
            elif not board.get("relink"):
                red.append(f"{it['key']} `{it['title']}` has no parent and this tracker cannot link an existing item — make it a sub-item of `{r['parent']}` by hand")
            else:
                reqs.append({"op": "link", "key": it["key"], "parent": r["parent"]})
        if it["column"] is None:   # an issue never added to the board (GitHub): added, in its state's column
            reqs.append({"op": "move", "key": it["key"], "column": flow[r["state"]], "close": flow[r["state"]] == flow["done"]})
    return reqs, red


_num = rest.ascii_int   # an ASCII decimal (`²` is refused) — one definition, in the transport


def _body(repo: Path, body: str) -> Path:
    """A row's body is a markdown file (`.md`) — any other path is refused, so no other file reaches the tracker or the repo."""
    p = (Path(body) if Path(body).is_absolute() else repo / body).resolve()
    if p.suffix != ".md" or not p.is_file():
        raise GateFault(f"the body `{clean(body)}` is not a markdown file (.md) — write the issue text to a .md file first")
    return p


def _body_text(repo: Path, body: str) -> str:
    try:
        return _body(repo, body).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise GateFault(f"the body `{clean(body)}` cannot be read ({clean(e, 200)})") from None


# ─── adapter: none (docs/backlog/state.md) ──────────────────────────────────────

def _cells(line: str) -> list[str]:
    body = line.strip()
    body = body[1:] if body.startswith("|") else body
    body = body[:-1] if body.endswith("|") and not body.endswith("\\|") else body
    return [c.strip().replace("\\|", "|") for c in re.split(r"(?<!\\)\|", body)]


def _esc(v) -> str:
    return str(v).replace("|", "\\|").replace("\n", " ")


def from_state(text: str) -> dict:
    m = FM_RE.match(text)
    fm = parse_yaml(m.group(1)) if m else {}
    cols = fm.get("board_columns") if isinstance(fm, dict) else None
    if not (isinstance(cols, list) and cols and all(isinstance(c, str) for c in cols)):
        raise GateFault(f"{STATE}: the frontmatter carries no `board_columns` list")
    items, header = [], None
    for line in text.splitlines():
        if not line.strip().startswith("|"):
            header = None
            continue
        cells = _cells(line)
        if header is None:
            header = cells
            continue
        if header[: len(LOCAL_COLS)] != list(LOCAL_COLS) or all(set(c) <= set(":- ") for c in cells) or all(c in EMPTY for c in cells):
            continue
        row = dict(zip(header, cells + [""] * (len(header) - len(cells))))   # a short row reads its missing cells empty
        none = lambda v: None if v in EMPTY else v
        items.append({"key": row["Local ID"], "title": row["Title"], "column": none(row["Status"]), "parent": none(row["Parent"]),
                      "labels": [x.strip() for x in row["Labels"].split(",") if x.strip() and x.strip() not in EMPTY],
                      "closed": row["Status"] == cols[-1], "ref": {}})
    return {"columns": [c.strip() for c in cols], "items": items, "relink": True, "closable": False}


class Local:
    def __init__(self, repo: Path):
        self.repo, self.path = repo, repo / STATE

    def _text(self) -> str:
        try:
            return self.path.read_text(encoding="utf-8")
        except FileNotFoundError:
            raise GateFault(f"{STATE} is missing — `BACKLOG --init-board` creates the local board") from None

    def read(self, touched=()) -> dict:
        return from_state(self._text())

    def apply(self, reqs: list[dict]) -> list[str]:
        text, made, touched = self._text(), {}, []
        board = from_state(text)
        for r in reqs:
            if r["op"] == "create":
                text, k = self._create(text, r, board, made)
                made[r["ident"]] = k
            elif r["op"] == "move":
                text, k = self._set(text, r["key"], "Status", r["column"]), r["key"]
            else:
                text, k = self._set(text, r["key"], "Parent", self._parent(r["parent"], board, made)), r["key"]
            touched.append(k)
        self.path.write_text(text, encoding="utf-8")
        return touched

    @staticmethod
    def _parent(ident, board, made):
        if not ident:
            return "—"
        if ident in made:
            return made[ident]
        hit = find(board, ident)
        return hit[0]["key"] if hit else "—"

    def _set(self, text: str, k: str, col: str, value: str) -> str:
        lines, header = text.split("\n"), None
        for n, line in enumerate(lines):
            if not line.strip().startswith("|"):
                header = None
                continue
            cells = _cells(line)
            if header is None:
                header = cells
                continue
            if header[: len(LOCAL_COLS)] == list(LOCAL_COLS) and cells and cells[0] == k:
                cells[header.index(col)] = value
                lines[n] = "| " + " | ".join(_esc(c) for c in cells) + " |"
                return "\n".join(lines)
        raise GateFault(f"{STATE}: no row {clean(k)}")

    def _create(self, text: str, r: dict, board: dict, made: dict) -> tuple[str, str]:
        m = FM_RE.match(text)
        fm = parse_yaml(m.group(1)) if m else {}
        n = fm.get("next_local_id") if isinstance(fm.get("next_local_id"), int) else len(board["items"]) + len(made) + 1
        k = f"L-{n:03d}"
        body = ""
        if r.get("body"):
            src = _body(self.repo, r["body"])
            home = (self.repo / BODIES).resolve()
            if src.parent == home:   # already a body file (BOPS § 5 naming): the row points at it
                body = f"{BODIES}/{src.name}"
            else:
                dst = home / f"{k}.md"
                dst.parent.mkdir(parents=True, exist_ok=True)
                dst.write_text(_body_text(self.repo, r["body"]), encoding="utf-8")
                body = f"{BODIES}/{k}.md"
        feat = re.match(r"^\[([^\]]+)\]", r["title"])
        cells = [k, feat.group(1) if feat else "—", r["title"], r["column"], ", ".join(r["labels"]) or "—", r.get("milestone") or "—",
                 self._parent(r.get("parent"), board, made), body or "—"]
        row = "| " + " | ".join(_esc(c) for c in cells) + " |"
        lines, header, last, placeholder = text.split("\n"), None, None, None
        for i, line in enumerate(lines):
            if not line.strip().startswith("|"):
                header = None
                continue
            cells_i = _cells(line)
            if header is None:
                header = cells_i
                continue
            if header[: len(LOCAL_COLS)] == list(LOCAL_COLS):
                last = i
                if all(c in EMPTY for c in cells_i) and not all(set(c) <= set(":- ") and c for c in cells_i):
                    placeholder = i
        if last is None:
            raise GateFault(f"{STATE}: no board table (| Local ID | … |)")
        if placeholder is not None:
            lines[placeholder] = row
        else:
            lines.insert(last + 1, row)
        text = "\n".join(lines)
        today = dt.datetime.now(dt.timezone.utc).date().isoformat()
        total = fm.get("total_issues") if isinstance(fm.get("total_issues"), int) else len(board["items"]) + len(made)
        for fk, fv in (("next_local_id", n + 1), ("total_issues", total + 1), ("last_updated", today)):
            text = re.sub(rf"(?m)^{fk}:.*$", f"{fk}: {fv}", text, count=1)
        return text, k


# ─── adapter: github (gh api graphql) ───────────────────────────────────────────

ISSUE_FIELDS = "id number title state parent { number } labels(first: 50) { nodes { name } }"
PROJECT_FIELDS = ('id field(name: "Status") { ... on ProjectV2SingleSelectField { id options { id name } } } '
                  "items(first: 100, after: $after) { pageInfo { hasNextPage endCursor } nodes { id "
                  'fieldValueByName(name: "Status") { ... on ProjectV2ItemFieldSingleSelectValue { name } } '
                  f"content {{ __typename ... on Issue {{ {ISSUE_FIELDS} repository {{ nameWithOwner }} }} }} }} }}")
Q_BOARD_NODE = f"query TrackerBoard($id: ID!, $after: String) {{ node(id: $id) {{ ... on ProjectV2 {{ {PROJECT_FIELDS} }} }} }}"
Q_BOARD_OWNER = ("query TrackerBoard($owner: String!, $number: Int!, $after: String) { repositoryOwner(login: $owner) { "
                 f"... on ProjectV2Owner {{ projectV2(number: $number) {{ {PROJECT_FIELDS} }} }} }} }}")
Q_ISSUES = ("query TrackerIssues($owner: String!, $name: String!, $after: String) { repository(owner: $owner, name: $name) { "
            f"issues(first: 100, after: $after, states: OPEN) {{ pageInfo {{ hasNextPage endCursor }} nodes {{ {ISSUE_FIELDS} }} }} }} }}")
Q_ISSUE = "query TrackerIssue($owner: String!, $name: String!, $number: Int!) { repository(owner: $owner, name: $name) { issue(number: $number) { id } } }"
M_ADD = "mutation TrackerAdd($project: ID!, $content: ID!) { addProjectV2ItemById(input: {projectId: $project, contentId: $content}) { item { id } } }"
M_SET = ("mutation TrackerSet($project: ID!, $item: ID!, $field: ID!, $option: String!) { updateProjectV2ItemFieldValue(input: "
         "{projectId: $project, itemId: $item, fieldId: $field, value: {singleSelectOptionId: $option}}) { projectV2Item { id } } }")
M_CLOSE = "mutation TrackerClose($id: ID!) { closeIssue(input: {issueId: $id}) { issue { id } } }"
M_REOPEN = "mutation TrackerReopen($id: ID!) { reopenIssue(input: {issueId: $id}) { issue { id } } }"
M_LINK = "mutation TrackerLink($parent: ID!, $child: ID!) { addSubIssue(input: {issueId: $parent, subIssueId: $child}) { issue { id } } }"


def _gh(args: list[str]) -> str:
    try:
        p = subprocess.run(["gh", *args], capture_output=True, text=True, timeout=60)
    except FileNotFoundError:
        raise GateFault("the GitHub CLI `gh` is not installed — see docs/backlog/tool-adapter.md § 0") from None
    except subprocess.TimeoutExpired:
        raise GateFault("`gh` did not answer within 60 s — transient: re-run") from None
    if p.returncode != 0:
        err = clean((p.stderr or p.stdout).strip().splitlines()[-1] if (p.stderr or p.stdout).strip() else f"exit {p.returncode}", 300)
        hint = " — authenticate: gh auth login --scopes repo,project,read:org" if re.search(r"auth|401|403|scope", err, re.I) else ""
        raise GateFault(f"GitHub refused the request ({err}){hint}")
    return p.stdout


def _project(doc: dict) -> dict:
    d = (doc or {}).get("data") or {}
    p = d.get("node") if "node" in d else ((d.get("repositoryOwner") or {}).get("projectV2"))
    if not isinstance(p, dict) or not p.get("id"):
        raise GateFault("the GitHub project was not found — check docs/backlog/project-config.json → project_ids (owner, project_number) and the token's `project` scope")
    return p


def from_github(boards: list[dict], issues: list[dict], slug: str) -> dict:
    """Recorded `TrackerBoard` pages + `TrackerIssues` pages → the one shape (the repository's issues only)."""
    p = _project(boards[0])
    field = p.get("field") or {}
    if not field.get("id"):
        raise GateFault("the GitHub project has no single-select `Status` field — `BACKLOG --init-board` (configure_board) creates it")
    items, seen = [], set()
    for page in boards:
        for n in ((_project(page).get("items") or {}).get("nodes") or []):
            c = n.get("content") or {}
            if c.get("__typename") != "Issue" or (c.get("repository") or {}).get("nameWithOwner", "").lower() != slug.lower():
                continue
            col = (n.get("fieldValueByName") or {}).get("name")
            items.append(_gh_item(c, col, n.get("id")))
            seen.add(c.get("number"))
    for page in issues:
        for c in ((((page or {}).get("data") or {}).get("repository") or {}).get("issues") or {}).get("nodes") or []:
            if c.get("number") not in seen:
                items.append(_gh_item(c, None, None))
                seen.add(c.get("number"))
    return {"columns": [o["name"] for o in field.get("options") or []], "items": items, "relink": True, "closable": True,
            "ref": {"project": p["id"], "field": field["id"], "options": {o["name"]: o["id"] for o in field.get("options") or []}}}


def _gh_item(c: dict, col, item_id) -> dict:
    return {"key": f"#{c['number']}", "title": c.get("title") or "", "column": col,
            "parent": f"#{c['parent']['number']}" if c.get("parent") else None,
            "labels": [x["name"] for x in ((c.get("labels") or {}).get("nodes") or [])], "closed": c.get("state") == "CLOSED",
            "ref": {"node": c.get("id"), "item": item_id}}


class GitHub:
    def __init__(self, repo: Path, pids: dict, gh=_gh):
        self.repo, self.gh = repo, gh
        owner, name, number = pids.get("owner"), pids.get("repo"), pids.get("project_number")
        if not owner or not name or not _num(number):
            raise GateFault(f"{CONFIG} → project_ids needs `owner`, `repo` and `project_number` — `BACKLOG --init-board` records them")
        self.owner, self.name = str(owner), str(name).split("/")[-1]
        if not GH_NAME.match(self.owner) or not GH_NAME.match(self.name):
            raise GateFault(f"{CONFIG} → project_ids `owner` and `repo` are GitHub names (letters, digits, . _ -)")
        self.number, self.node = int(number), pids.get("project_node_id") if str(pids.get("project_node_id") or "").startswith("PVT_") else None
        self.board = None

    def _q(self, query: str, **v) -> dict:
        args = ["api", "graphql", "-f", f"query={query}"]
        for k, val in v.items():
            if val is not None:
                args += ["-F" if isinstance(val, int) else "-f", f"{k}={val}"]
        try:
            doc = json.loads(self.gh(args) or "null")
        except ValueError:
            raise GateFault("GitHub answered something that is not JSON — transient: re-run") from None
        if isinstance(doc, dict) and doc.get("errors"):
            raise GateFault("GitHub refused the request: " + clean("; ".join(str(e.get("message")) for e in doc["errors"] if isinstance(e, dict)), 300))
        return doc

    def _pages(self, query: str, path, **v) -> list[dict]:
        pages, after = [], None
        while True:
            doc = self._q(query, after=after, **v)
            pages.append(doc)
            conn = path(doc) or {}
            info = conn.get("pageInfo") or {}
            if not info.get("hasNextPage"):
                return pages
            after = info.get("endCursor")

    def read(self, touched=()) -> dict:
        if self.node:
            boards = self._pages(Q_BOARD_NODE, lambda d: _project(d).get("items"), id=self.node)
        else:
            boards = self._pages(Q_BOARD_OWNER, lambda d: _project(d).get("items"), owner=self.owner, number=self.number)
        issues = self._pages(Q_ISSUES, lambda d: (((d or {}).get("data") or {}).get("repository") or {}).get("issues"), owner=self.owner, name=self.name)
        self.board = from_github(boards, issues, f"{self.owner}/{self.name}")
        return self.board

    def apply(self, reqs: list[dict]) -> list[str]:
        b = self.board or self.read()
        ref, made, touched = b["ref"], {}, []
        nodes = {i["key"]: i["ref"] for i in b["items"]}
        for r in reqs:
            if r["op"] == "create":
                k = self._create(r)
                nodes[k] = {"node": self._node(k), "item": None}
                made[r["ident"]] = k
                if r.get("parent"):
                    self._q(M_LINK, parent=nodes[self._key(r["parent"], b, made)]["node"], child=nodes[k]["node"])
                self._move(ref, nodes[k], r["column"], r["close"], closed=False)
            elif r["op"] == "move":
                k = r["key"]
                it = next(i for i in b["items"] if i["key"] == k)
                self._move(ref, nodes[k], r["column"], r["close"], closed=it["closed"])
            else:
                k = r["key"]
                self._q(M_LINK, parent=nodes[self._key(r["parent"], b, made)]["node"], child=nodes[k]["node"])
            touched.append(k)
        return touched

    @staticmethod
    def _key(ident, b, made) -> str:
        if ident in made:
            return made[ident]
        hit = find(b, ident)
        if len(hit) != 1:
            raise GateFault(f"the parent `{clean(ident)}` is not one item on the board")
        return hit[0]["key"]

    def _create(self, r: dict) -> str:
        args = ["issue", "create", "--repo", f"{self.owner}/{self.name}", "--title", r["title"]]
        args += ["--body-file", str(_body(self.repo, r["body"]))] if r.get("body") else ["--body", ""]
        for lab in r.get("labels") or []:
            args += ["--label", lab]
        if r.get("milestone"):
            args += ["--milestone", r["milestone"]]
        out = self.gh(args).strip()
        url = out.splitlines()[-1] if out else ""
        m = re.search(r"/issues/(\d+)\s*$", url)
        if not m:
            raise GateFault(f"`gh issue create` printed no issue url ({clean(url, 200)})")
        return f"#{m.group(1)}"

    def _node(self, k: str) -> str:
        doc = self._q(Q_ISSUE, owner=self.owner, name=self.name, number=int(k.lstrip("#")))
        node = ((((doc or {}).get("data") or {}).get("repository") or {}).get("issue") or {}).get("id")
        if not node:
            raise GateFault(f"GitHub has no issue {k} right after creating it — transient: re-run (nothing is created twice)")
        return node

    def _move(self, ref: dict, n: dict, column: str, close: bool, closed: bool):
        if not n.get("item"):
            doc = self._q(M_ADD, project=ref["project"], content=n["node"])
            n["item"] = ((((doc or {}).get("data") or {}).get("addProjectV2ItemById") or {}).get("item") or {}).get("id")
            if not n["item"]:
                raise GateFault("GitHub did not return the project item it added — transient: re-run")
        self._q(M_SET, project=ref["project"], item=n["item"], field=ref["field"], option=ref["options"][column])
        if close and not closed:
            self._q(M_CLOSE, id=n["node"])
        elif closed and not close:
            self._q(M_REOPEN, id=n["node"])


# ─── adapter: jira (REST) ───────────────────────────────────────────────────────

def _http(method: str, url: str, headers: dict, body=None):
    """→ (status, parsed JSON | None) through the shared transport (`rest.call`, EVOL-080): no redirect followed, 429 once."""
    return rest.call("Jira", "set project_ids.site to the address the API answers on",
                     "the token in JIRA_API_TOKEN (and JIRA_USER_EMAIL on Cloud) cannot do this", method, url, headers, body)


def _adf(text: str) -> dict:
    paras = [p for p in (text or "").split("\n\n") if p.strip()]
    return {"type": "doc", "version": 1, "content": [{"type": "paragraph", "content": [{"type": "text", "text": p.strip()}]} for p in paras]}


def from_jira(config: dict, pages: list[dict], extra: list[dict] = ()) -> dict:
    """Board configuration + search pages (+ issues read one by one, which win) → the one shape."""
    cols = ((config or {}).get("columnConfig") or {}).get("columns") or []
    if not cols:
        raise GateFault("the Jira board configuration lists no column — check project_ids.board_id")
    where = {str(s.get("id")): c.get("name") for c in cols for s in (c.get("statuses") or [])}
    issues = {}
    for i in [x for p in pages for x in ((p or {}).get("issues") or [])] + list(extra):
        f = i.get("fields") or {}
        st = f.get("status") or {}
        issues[i.get("key")] = {"key": i.get("key"), "title": f.get("summary") or "", "column": where.get(str(st.get("id"))),
                                "parent": (f.get("parent") or {}).get("key"), "labels": list(f.get("labels") or []),
                                "closed": (st.get("statusCategory") or {}).get("key") == "done",
                                "ref": {"id": i.get("id"), "subtask": bool((f.get("issuetype") or {}).get("subtask"))}}
    return {"columns": [c.get("name") for c in cols], "items": list(issues.values()), "relink": False, "closable": False,
            "ref": {"statuses": {c.get("name"): {str(s.get("id")) for s in (c.get("statuses") or [])} for c in cols}}}


class Jira:
    def __init__(self, repo: Path, pids: dict, fetch=_http, env: dict | None = None):
        env = os.environ if env is None else env
        site, pkey, board = str(pids.get("site") or "").rstrip("/"), str(pids.get("project_key") or ""), str(pids.get("board_id") or "")
        u = urllib.parse.urlparse(site)
        if u.scheme != "https" or not u.hostname or u.username is not None or u.password is not None or not JIRA_KEY.match(pkey) or not _num(board):
            raise GateFault(f"{CONFIG} → project_ids needs `site` (https://…, no user or password), `project_key` (e.g. ACME) and `board_id` — `BACKLOG --init-board` records them")
        tok = env.get("JIRA_API_TOKEN")
        if not tok:
            raise GateFault("JIRA_API_TOKEN is not set — export it from the secret named in docs/setup.md → project_tracking.token")
        self.cloud = u.hostname.endswith(".atlassian.net")
        if self.cloud:
            mail = env.get("JIRA_USER_EMAIL")
            if not mail:
                raise GateFault("JIRA_USER_EMAIL is not set — Jira Cloud authenticates the API token with the account's email")
            self.auth = {"Authorization": "Basic " + base64.b64encode(f"{mail}:{tok}".encode()).decode()}
        else:
            self.auth = {"Authorization": f"Bearer {tok}"}
        self.repo, self.site, self.pkey, self.board_id, self.fetch = repo, site, pkey, board, fetch
        self.api = f"{site}/rest/api/{'3' if self.cloud else '2'}"
        self.board, self.meta, self.made = None, None, []

    def _call(self, method: str, path: str, body=None):
        return self.fetch(method, path if path.startswith("http") else f"{self.api}{path}", self.auth, body)[1]

    def _search(self) -> list[dict]:
        jql, pages = f'project = "{self.pkey}" ORDER BY key ASC', []
        if self.cloud:
            body = {"jql": jql, "fields": JIRA_FIELDS, "maxResults": 100}
            if self.made:
                body["reconcileIssues"] = [int(i) for i in self.made[-50:]]   # read-after-write for this run's own creations
            seen = set()
            while True:
                doc = self._call("POST", "/search/jql", body) or {}
                pages.append(doc)
                tok = doc.get("nextPageToken")
                if doc.get("isLast") is True or not tok:
                    return pages
                if tok in seen:
                    raise GateFault("Jira returned one search page token twice — the search does not advance; re-run later")
                seen.add(tok); body = {**body, "nextPageToken": tok}
        start = 0
        while True:
            doc = self._call("POST", "/search", {"jql": jql, "fields": JIRA_FIELDS, "startAt": start, "maxResults": 100}) or {}
            got = doc.get("issues") or []
            pages.append(doc)
            start += len(got)
            if not got or (isinstance(doc.get("total"), int) and start >= doc["total"]):
                return pages

    def read(self, touched=()) -> dict:
        config = self._call("GET", f"{self.site}/rest/agile/1.0/board/{self.board_id}/configuration")
        extra = [self._call("GET", f"/issue/{urllib.parse.quote(k, safe='')}?fields={','.join(JIRA_FIELDS)}") or {} for k in touched if JIRA_ISSUE.match(k)]
        self.board = from_jira(config, self._search(), extra)
        return self.board

    def _project(self) -> dict:
        if self.meta is None:
            self.meta = self._call("GET", f"/project/{self.pkey}") or {}
        return self.meta

    def _type(self, sub: bool) -> str:
        types = [t for t in (self._project().get("issueTypes") or []) if bool(t.get("subtask")) == sub]
        pick = next((t for t in types if not sub and t.get("name") == "Task"), types[0] if types else None)
        if not pick:
            raise GateFault(f"the Jira project {self.pkey} has no {'sub-task' if sub else 'standard'} issue type")
        return str(pick["id"])

    def _version(self, name: str) -> str:
        v = next((x for x in (self._project().get("versions") or []) if x.get("name") == name), None)
        if not v:
            raise GateFault(f"the Jira project {self.pkey} has no version `{clean(name)}` — create the milestone first (create_milestone)")
        return str(v["id"])

    def apply(self, reqs: list[dict]) -> list[str]:
        b = self.board or self.read()
        made, touched = {}, []
        for r in reqs:
            if r["op"] == "create":
                k = self._create(r, b, made)
                made[r["ident"]] = k
                got = self._call("GET", f"/issue/{urllib.parse.quote(k, safe='')}?fields={','.join(JIRA_FIELDS)}") or {}
                sid = str(((got.get("fields") or {}).get("status") or {}).get("id"))
                if sid not in b["ref"]["statuses"].get(r["column"], set()):
                    self._move(k, r["column"], b)
            elif r["op"] == "move":
                k = r["key"]
                self._move(k, r["column"], b)
            else:
                raise GateFault("Jira cannot link an existing item under a parent — the planner never asks it")
            touched.append(k)
        return touched

    def _create(self, r: dict, b: dict, made: dict) -> str:
        parent = None
        if r.get("parent"):
            parent = made.get(r["parent"])
            if not parent:
                hit = find(b, r["parent"])
                if len(hit) != 1:
                    raise GateFault(f"the parent `{clean(r['parent'])}` is not one item on the board")
                parent = hit[0]["key"]
        body = ""
        if r.get("body"):
            body = _body_text(self.repo, r["body"])
        f = {"project": {"key": self.pkey}, "summary": r["title"], "issuetype": {"id": self._type(bool(parent))}, "labels": list(r.get("labels") or [])}
        if body:
            f["description"] = _adf(body) if self.cloud else body
        if parent:
            f["parent"] = {"key": parent}
        if r.get("milestone"):
            f["fixVersions"] = [{"id": self._version(r["milestone"])}]
        doc = self._call("POST", "/issue", {"fields": f}) or {}
        if not doc.get("key"):
            raise GateFault(f"Jira created no issue for `{clean(r['title'], 120)}`")
        if _num(doc.get("id")):
            self.made.append(str(doc["id"]))
        return doc["key"]

    def _move(self, k: str, column: str, b: dict):
        want = b["ref"]["statuses"].get(column) or set()
        ts = (self._call("GET", f"/issue/{urllib.parse.quote(k, safe='')}/transitions") or {}).get("transitions") or []
        t = next((t for t in ts if str((t.get("to") or {}).get("id")) in want), None)
        if not t:
            raise GateFault(f"{k}: the workflow has no transition into the `{clean(column)}` column from its current status — add one in the Jira workflow")
        self._call("POST", f"/issue/{urllib.parse.quote(k, safe='')}/transitions", {"transition": {"id": str(t["id"])}})


# ─── commands ───────────────────────────────────────────────────────────────────

def adapter(repo: Path, c: dict, **inject):
    if c["adapter"] == "none":
        return Local(repo)
    if c["adapter"] == "github":
        return GitHub(repo, ids(repo), **({"gh": inject["gh"]} if "gh" in inject else {}))
    return Jira(repo, ids(repo), **{k: v for k, v in inject.items() if k in ("fetch", "env")})


def _result(c: dict, ident: str, **kw) -> dict:
    return {"ok": not kw.get("red"), "adapter": c["adapter"], "ident": ident, "did": kw.get("did", []), "red": kw.get("red", []),
            "requests": kw.get("requests", [])}


def _settle(ad, reqs: list[dict], replan) -> list[str]:
    """Apply, read back (the keys written one by one), plan again: what is left — a request or a red — is red."""
    touched = ad.apply(reqs)
    left, red = replan(ad.read(touched=touched))
    return [f"the board did not take `{r.get('op')}` {r.get('key') or r.get('title')} → {r.get('column') or r.get('parent')}" for r in left] + red


def _again(b: dict, ident: str, col: str, done: str) -> tuple[list[dict], list[str]]:
    hit = find(b, ident)
    if len(hit) != 1:
        return [], [f"`{ident}` is {len(hit)} items on the board after the write, not one"]
    return plan_move(b, hit[0], col, done), []


def _aligned(repo: Path, ac: str, feature: str | None) -> list[str]:
    m = re.fullmatch(r"AC-(.+)-\d+", str(ac or ""))
    if not m:
        return [f"`{clean(ac)}` is not an accepted-change id (AC-<feature>-<N>)"]
    if feature and m.group(1) != feature:
        return [f"{ac} is an accepted change of {m.group(1)}, not of {feature} — name a realignment of this item's feature"]
    log = repo / aligned_mod.LOG.format(fid=m.group(1))
    try:
        lines = log.read_text(encoding="utf-8").splitlines()
    except OSError:
        return [f"{aligned_mod.LOG.format(fid=m.group(1))} is missing — no accepted change {ac} is recorded"]
    for ln in lines:
        try:
            e = json.loads(ln)
        except ValueError:
            continue
        if isinstance(e, dict) and e.get("action") == aligned_mod.ACTION and e.get("id") == ac:
            return [f"{ac}: {p}" for p in aligned_mod.ratification(e)]
    return [f"no accepted change {ac} in {aligned_mod.LOG.format(fid=m.group(1))}"]


def start(repo: Path, feature: str | None = None, phase: str | None = None, item: str | None = None, aligns: str | None = None, **inject) -> dict:
    c = cfg(repo)
    ident = item.strip() if item else phase_ident(feature, phase, preset(repo))
    ad = adapter(repo, c, **inject)
    board = ad.read()
    _flow_on(board, c["flow"])
    hits = find(board, ident)
    if len(hits) != 1:
        why = (f"no item `{ident}` on the board — create it first (`BACKLOG --plan-feature`, or gate.py tracker --ensure)" if not hits else
               f"`{ident}` matches {len(hits)} items ({', '.join(h['key'] for h in hits)}) — a duplicate; close the extra one by hand")
        return _result(c, ident, red=[why])
    it, flow = hits[0], c["flow"]
    if it["column"] == flow["done"] or (board.get("closable") and it["closed"]):
        if not aligns:
            return _result(c, ident, red=[f"{it['key']} is Done — new work on a closed phase opens a refinement item ({head(it['title']).rstrip(':')}-R<k>:), "
                                          "or names the ratified realignment it carries out (--aligns AC-…)"])
        own = feature or (f.group(1) if (f := re.match(r"^\[([^\]]+)\]", it["title"])) else None)
        problems = _aligned(repo, aligns, own)
        return _result(c, ident, red=problems, did=[] if problems else [f"{it['key']} stays {flow['done']} — the realignment {aligns} is ratified"])
    reqs = plan_move(board, it, flow["in-progress"], flow["done"])
    if not reqs:
        return _result(c, ident, did=[f"{it['key']} already {flow['in-progress']}"])
    red = _settle(ad, reqs, lambda b: _again(b, ident, flow["in-progress"], flow["done"]))
    return _result(c, ident, red=red, did=[] if red else [f"{it['key']} → {flow['in-progress']}"], requests=reqs)


def move(repo: Path, ident: str, state: str, **inject) -> dict:
    c = cfg(repo)
    if state not in STATES:
        raise GateFault(f"`{clean(state)}` is not a lifecycle state ({', '.join(STATES)})")
    ident, col = ident.strip(), c["flow"][state]
    ad = adapter(repo, c, **inject)
    board = ad.read()
    _flow_on(board, c["flow"])
    hits = find(board, ident)
    if len(hits) != 1:
        return _result(c, ident, red=[f"no item `{ident}` on the board" if not hits else f"`{ident}` matches {len(hits)} items ({', '.join(h['key'] for h in hits)})"])
    reqs = plan_move(board, hits[0], col, c["flow"]["done"])
    if not reqs:
        return _result(c, ident, did=[f"{hits[0]['key']} already {col}"])
    red = _settle(ad, reqs, lambda b: _again(b, ident, col, c["flow"]["done"]))
    return _result(c, ident, red=red, did=[] if red else [f"{hits[0]['key']} → {col}"], requests=reqs)


def rows_file(repo: Path, path: str) -> list:
    p = Path(path) if Path(path).is_absolute() else repo / path
    try:
        rows = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise GateFault(f"the ensure file {path} is not readable JSON ({e})") from None
    if not isinstance(rows, list) or not rows:
        raise GateFault(f"the ensure file {path} is a non-empty list of rows {{title, ident?, body?, labels?, parent?, milestone?, state?}}")
    return rows


def sub_increment_rows(repo: Path, feature: str) -> list[dict]:
    parent = phase_ident(feature, "implement", preset(repo))
    rel = f"docs/spec/{feature}/increment_plan.md"
    try:
        text = (repo / rel).read_text(encoding="utf-8")
    except OSError:
        raise GateFault(f"{rel} is missing — the sub-increments come from its § 1") from None
    rows = []
    for m in train_mod.ROW_RE.finditer(text):
        scope = m.group(3).split("·")[0].strip().strip("*").strip()
        title = f"[{feature}] INC-{m.group(1)} / SUB-{m.group(1)}-{m.group(2)}: {scope or 'sub-increment'}"
        if head(title) not in {head(r["title"]) for r in rows}:
            rows.append({"title": title, "parent": parent, "labels": ["phase:implement"]})
    if not rows:
        raise GateFault(f"{rel} declares no sub-increment (- SUB-N-M: …) — nothing to create")
    return rows


def ensure(repo: Path, rows: list, dry_run: bool = False, **inject) -> dict:
    c = cfg(repo)
    ad = adapter(repo, c, **inject)
    board = ad.read()
    reqs, red = plan_ensure(board, rows, c["flow"])
    ident = f"{len(rows)} row(s)"
    for q in reqs:
        if q["op"] == "create" and q.get("body"):
            _body_text(repo, q["body"])   # every body a readable .md before the first write
    if red or dry_run or not reqs:
        did = [] if red or reqs else ["every item already on the board — nothing to create"]
        return _result(c, ident, red=red, requests=reqs, did=did)
    left = _settle(ad, reqs, lambda b: plan_ensure(b, rows, c["flow"]))
    made = sum(r["op"] == "create" for r in reqs)
    return _result(c, ident, red=left, requests=reqs, did=[] if left else [f"{made} created, {len(reqs) - made} linked or placed"])


def render(r: dict) -> str:
    head_ = f"tracker ({r['adapter']}): {'GREEN' if r['ok'] else 'RED'} — {r['ident']}"
    lines = [head_] + [f"  {d}" for d in r["did"]] + [f"  ✗ {x}" for x in r["red"]]
    if r["requests"] and (not r["ok"] or not r["did"]):
        lines += ["  planned:"] + [f"    {q['op']} {q.get('key') or q.get('title')} → {q.get('column') or q.get('parent')}" for q in r["requests"]]
    return "\n".join(lines)
